#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Provided by the candidate in solution.c */
int ring_push(int *buf, int capacity, int *head, int *tail, int value);
int ring_pop(int *buf, int capacity, int *head, int *tail, int *value_out);

int main(void)
{
    int capacity;
    if (scanf("%d", &capacity) != 1 || capacity < 2) {
        return 1;
    }

    int *buf = calloc((size_t)capacity, sizeof *buf);
    if (buf == NULL) {
        return 1;
    }
    int head = 0, tail = 0;

    char op[8];
    while (scanf("%7s", op) == 1) {
        if (strcmp(op, "PUSH") == 0) {
            int value;
            if (scanf("%d", &value) != 1) {
                return 1;
            }
            int ok = ring_push(buf, capacity, &head, &tail, value);
            printf("%s\n", ok ? "OK" : "FULL");
        } else if (strcmp(op, "POP") == 0) {
            int value;
            int ok = ring_pop(buf, capacity, &head, &tail, &value);
            if (ok) {
                printf("POP %d\n", value);
            } else {
                printf("EMPTY\n");
            }
        } else {
            printf("UNKNOWN OP %s\n", op);
            return 1;
        }
    }

    free(buf);
    return 0;
}

