"""Random PUSH/POP traces against a range of capacities, including ones that
deliberately drive the buffer to full and back to empty."""


def generate(rng, count):
    return [_case(rng, index + 1) for index in range(count)]


def _case(rng, index):
    capacity = rng.randint(2, 6)
    steps = rng.randint(4, 12)
    lines = ["%d" % capacity]
    value_pool = list(range(1, 50))
    for _ in range(steps):
        if rng.random() < 0.6:
            lines.append("PUSH %d" % rng.choice(value_pool))
        else:
            lines.append("POP")
    return {
        "name": "a random trace, capacity %d #%d" % (capacity, index),
        "stdin": "\n".join(lines) + "\n",
        "description": "%d operation(s) against a buffer that holds at "
                       "most %d item(s)." % (steps, capacity - 1),
    }
